using Controllers.Services;
using Photon.Pun;
using UnityEngine;

namespace Controllers.Network
{
    public class PhotonObjectService : INetworkObjectService
    {
        public GameObject Instantiate(string prefabName, Vector3 position, Quaternion rotation)
        {
            return PhotonNetwork.Instantiate(prefabName, position, rotation);
        }

        public GameObject InstantiateRoomObject(string prefabName, Vector3 position, Quaternion rotation)
        {
            return PhotonNetwork.InstantiateRoomObject(prefabName, position, rotation);
        }

        public void InvokeRPC(MonoBehaviour source, string methodName, NetworkTarget target, params object[] parameters)
        {
            PhotonView photonView = source.GetComponent<PhotonView>();
            if (photonView == null)
            {
                Debug.LogWarning($"[PhotonObjectService] {source.name} 上没有 PhotonView 组件，无法调用 RPC {methodName}");
                return;
            }
            photonView.RPC(methodName, NetworkTargetMapper.ToRpcTarget(target), parameters);
        }

        public int GetViewID(Component component)
        {
            PhotonView photonView = component.GetComponent<PhotonView>();
            return photonView != null ? photonView.ViewID : -1;
        }

        public int GetViewID(GameObject gameObject)
        {
            if (gameObject == null) return -1;
            PhotonView photonView = gameObject.GetComponent<PhotonView>();
            return photonView != null ? photonView.ViewID : -1;
        }

        public GameObject FindByViewID(int viewId)
        {
            PhotonView photonView = PhotonView.Find(viewId);
            return photonView != null ? photonView.gameObject : null;
        }

        public string GetOwnerNickname(MonoBehaviour source)
        {
            if (source == null) return "";
            PhotonView pv = source.GetComponentInParent<PhotonView>();
            return pv != null && pv.Owner != null ? pv.Owner.NickName : "";
        }

        public int GetOwnerActorNumber(Component source)
        {
            if (source == null) return -1;
            PhotonView pv = source.GetComponentInParent<PhotonView>();
            return pv != null && pv.Owner != null ? pv.Owner.ActorNumber : -1;
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using ExitGames.Client.Photon;
using Photon.Pun;
using Managers;
using Core;
using Controllers.Services;
using Controllers.Player;
using UI;
using Hashtable = ExitGames.Client.Photon.Hashtable;

namespace Controllers.Network
{
    /// <summary>
    /// 玩家生成、生成点管理、角色切换逻辑（从 Launcher 拆分）
    /// 非 MonoBehaviour 纯逻辑类，由 Launcher 持有和驱动
    /// </summary>
    public class SpawnPointManager
    {
        private readonly Launcher _launcher;
        private readonly GameObject _currentlySelectedCharacter;

        private InputField _nameUI;
        private Photon.Realtime.Player _localPlayer;
        private GameObject _localPlayerObject;

        public GameObject LocalPlayerObject => _localPlayerObject;
        public Photon.Realtime.Player LocalPlayer => _localPlayer;

        public SpawnPointManager(Launcher launcher, GameObject currentlySelectedCharacter)
        {
            _launcher = launcher;
            _currentlySelectedCharacter = currentlySelectedCharacter;
        }

        /// <summary>大厅 UI 初始化完成后延迟注入 nameUI</summary>
        public void SetNameUI(InputField nameUI) => _nameUI = nameUI;

        // ==================== 玩家生成入口 ====================

        /// <summary>玩家加入房间 / 场景加载完成后的统一生成入口</summary>
        public void CreatedOrJoinedRoom()
        {
            if (SceneManager.GetActiveScene().buildIndex < 1)
            {
                Debug.Log("[SpawnPointManager] 当前不是游戏场景，跳过玩家生成");
                return;
            }
            ServiceLocator.Get<GameManager>().FindSpawnPoints();
            Debug.Log("[SpawnPointManager] 执行 CreatedOrJoinedRoom");

            EnsurePlayerManagerExists();

            GameObject player = SpawnPlayer();

            if (player != null)
            {
                InitializePlayerSettings(player);
                SetupPlayerUI(player);
            }

            SetupRoomInfo();
        }

        /// <summary>大厅场景延迟生成角色</summary>
        public IEnumerator SpawnPlayerAfterDelay()
        {
            yield return new WaitForEndOfFrame();

            yield return new WaitUntil(() =>
                ServiceLocator.Get<GameManager>() != null && ServiceLocator.Get<GameManager>().GetEmptySpawnPoint() != null
            );

            ApplySavedCharacter();

            GameObject player = SpawnPlayer();
            if (player != null)
            {
                InitializePlayerSettings(player);
                SetupPlayerUI(player);
                Debug.Log("[SpawnPointManager] 在大厅重新生成角色");
            }
        }

        // ==================== 核心：生成玩家 ====================

        public GameObject SpawnPlayer()
        {
            int localActorNumber = NetworkServiceLocator.PlayerService.GetLocalActorNumber();
            var gameManager = ServiceLocator.Get<GameManager>();

            // 根据 ActorNumber 确定性地分配生成点（不同玩家必然得到不同生成点）
            ISpawnPoint sp = gameManager.GetSpawnPointForPlayer(localActorNumber);
            Transform spawnPoint = (sp as MonoBehaviour)?.transform;

            // 仅当确定性分配的生成点被"其他"玩家占用时才回退（RPC 同步滞后期间 IsEmpty 可能误报）
            if (sp != null && !sp.IsEmpty() && sp.GetOccupiedByPlayer() != localActorNumber)
            {
                sp = gameManager.GetEmptySpawnPoint()?.GetComponent<ISpawnPoint>();
                spawnPoint = (sp as MonoBehaviour)?.transform;
            }

            if (spawnPoint == null)
            {
                Debug.LogError("[SpawnPointManager] 没有可用的生成点！");
                return null;
            }

            if (sp != null)
            {
                sp.SetOccupied(true, localActorNumber);
            }

            Vector3 spawnPosition = CalculateSpawnPosition(spawnPoint);

            GameObject player = PhotonNetwork.Instantiate(
                _currentlySelectedCharacter.name,
                spawnPosition,
                spawnPoint.rotation
            );

            player.transform.rotation = Quaternion.Euler(0, spawnPoint.rotation.eulerAngles.y, 0);
            player.name = "Player_" + PhotonNetwork.LocalPlayer.UserId;

            if (sp != null)
            {
                var props = new Hashtable { { PlayerPropertyKeys.SpawnPoint, sp.Id } };
                PhotonNetwork.LocalPlayer.SetCustomProperties(props);
            }

            return player;
        }

        // ==================== 重新生成 / 角色切换 ====================

        public void RespawnCharacter()
        {
            int currentSpawnPointId = -1;
            if (PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
            {
                currentSpawnPointId = (int)PhotonNetwork.LocalPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
            }

            if (_localPlayerObject != null)
            {
                PhotonNetwork.Destroy(_localPlayerObject);
            }

            GameObject newPlayer = RespawnAtSpawnPoint(currentSpawnPointId);

            if (newPlayer != null)
            {
                InitializePlayerSettings(newPlayer);
                SetupPlayerUI(newPlayer);
                Debug.Log($"[SpawnPointManager] 在原生成点 {currentSpawnPointId} 重新生成角色");
            }
        }

        private GameObject RespawnAtSpawnPoint(int spawnPointId)
        {
            ISpawnPoint targetSpawnPoint = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);

            if (targetSpawnPoint == null)
            {
                Debug.LogWarning($"[SpawnPointManager] 找不到ID为 {spawnPointId} 的生成点，使用第一个空闲生成点");
                return SpawnPlayer();
            }

            int localActorNumber = NetworkServiceLocator.PlayerService.GetLocalActorNumber();
            targetSpawnPoint.SetOccupied(true, localActorNumber);

            Transform spawnTransform = ((MonoBehaviour)targetSpawnPoint).transform;
            Vector3 spawnPosition = CalculateSpawnPosition(spawnTransform);

            GameObject player = PhotonNetwork.Instantiate(
                _currentlySelectedCharacter.name,
                spawnPosition,
                spawnTransform.rotation
            );

            player.transform.rotation = Quaternion.Euler(0, spawnTransform.rotation.eulerAngles.y, 0);
            player.name = "Player_" + PhotonNetwork.LocalPlayer.UserId;

            return player;
        }

        public void SwitchCharacter(string newCharacterName)
        {
            _currentlySelectedCharacter.name = newCharacterName;
            RespawnCharacter();
        }

        // ==================== 生成点清理 ====================

        /// <summary>清理本地玩家的生成点占用（退出房间前调用）</summary>
        public void ClearLocalPlayerSpawnPoint()
        {
            if (!PhotonNetwork.IsConnected || !PhotonNetwork.InRoom)
                return;

            if (PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
            {
                int spawnPointId = (int)PhotonNetwork.LocalPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
                ISpawnPoint sp = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);
                if (sp != null && (sp as MonoBehaviour) != null && sp.GetOccupiedByPlayer() == PhotonNetwork.LocalPlayer.ActorNumber)
                {
                    sp.ForceRelease();
                    Debug.Log("[SpawnPointManager] 退出前释放生成点");
                }
            }
        }

        /// <summary>其他玩家离开房间时释放其生成点（由 Launcher.OnPlayerLeftRoom 委托）</summary>
        public void HandlePlayerLeftRoom(Photon.Realtime.Player otherPlayer)
        {
            Debug.Log($"[SpawnPointManager] 玩家 {otherPlayer.NickName} 离开房间");
            if (!PhotonNetwork.IsConnected || !PhotonNetwork.InRoom)
            {
                Debug.LogWarning("[SpawnPointManager] 连接状态异常，跳过生成点释放");
                return;
            }
            if (otherPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
            {
                int spawnPointId = (int)otherPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
                ISpawnPoint sp = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);
                if (sp != null)
                {
                    sp.ForceRelease();
                    Debug.Log($"[SpawnPointManager] 释放玩家 {otherPlayer.NickName} 占用的生成点 {spawnPointId}");
                }
            }
        }

        /// <summary>Launcher OnDestroy 时清理本地生成点</summary>
        public void HandleDestroy()
        {
            if (PhotonNetwork.IsConnected && PhotonNetwork.InRoom)
            {
                if (PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.SpawnPoint))
                {
                    int spawnPointId = (int)PhotonNetwork.LocalPlayer.CustomProperties[PlayerPropertyKeys.SpawnPoint];
                    ISpawnPoint sp = ServiceLocator.Get<GameManager>().GetSpawnPointById(spawnPointId);
                    if (sp != null && (sp as MonoBehaviour) != null)
                    {
                        sp.ForceRelease();
                    }
                }
            }
        }

        // ==================== 玩家初始化 ====================

        private void InitializePlayerSettings(GameObject player)
        {
            if (!EventChannelLocator.MainContainer.gameSettings.IsStayLobby)
            {
                GameObject vcam = player.transform.Find("VirtualCamera")?.gameObject;
                if (vcam != null)
                {
                    vcam.SetActive(true);
                }
            }
            else
            {
                player.transform.LookAt(
                    new Vector3(0.182999998f, player.transform.position.y, -0.219999999f)
                );
            }
        }

        private void SetupPlayerUI(GameObject player)
        {
            _localPlayer = PhotonNetwork.LocalPlayer;
            if (string.IsNullOrEmpty(_localPlayer.NickName))
                _localPlayer.NickName = "玩家" + _localPlayer.UserId;

            if (_nameUI != null)
            {
                _nameUI.text = _localPlayer.NickName;
            }

            var worldSpaceUI = player.GetComponentInChildren<WordlSpaceUI>();
            if (worldSpaceUI != null)
            {
                worldSpaceUI.UpDatePlayerName(_localPlayer.NickName);
            }

            _localPlayerObject = player;
        }

        // ==================== 辅助方法 ====================

        public void EnsurePlayerManagerExists()
        {
            if (PlayerManager.instance == null)
            {
                PlayerManager existingPM = Object.FindObjectOfType<PlayerManager>();
                if (existingPM == null)
                {
                    GameObject pmObj = new GameObject("PlayerManager");
                    pmObj.AddComponent<PlayerManager>();
                    Debug.Log("[SpawnPointManager] 创建 PlayerManager");
                }
            }
            else
            {
                EventChannelLocator.MainContainer.gameActionChannel.Raise(Core.Channels.General.GameActionType.SyncAllPlayers);
            }
        }

        private Vector3 CalculateSpawnPosition(Transform spawnPoint)
        {
            if (EventChannelLocator.MainContainer.gameSettings.IsStayLobby)
            {
                return spawnPoint.position;
            }

            Vector2 randomCircle = Random.insideUnitCircle * 10.0f;
            Vector3 randomOffset = new Vector3(randomCircle.x, spawnPoint.position.y, randomCircle.y);
            return spawnPoint.position + spawnPoint.TransformVector(randomOffset);
        }

        private void ApplySavedCharacter()
        {
            int savedIndex = SaveManager.SelectedCharacterIndex;
            switch (savedIndex)
            {
                case CharactorIndex.BingNv:
                    _currentlySelectedCharacter.name = CharactorName.BingNv;
                    break;
                case CharactorIndex.WiZardBoy:
                default:
                    _currentlySelectedCharacter.name = CharactorName.WiZardBoy;
                    break;
            }
        }

        private void SetupRoomInfo()
        {
            GameObject roomNameObj = GameObject.Find("RoomName");
            if (roomNameObj != null && PhotonNetwork.CurrentRoom != null)
            {
                Text roomNameText = roomNameObj.GetComponent<Text>();
                if (roomNameText != null)
                {
                    roomNameText.text = PhotonNetwork.CurrentRoom.Name;
                }
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using Core;
using Controllers.Combat;
using Controllers.Combat.ImpactCannon;
using Photon.Pun;
using UnityEngine;
using Controllers.Network;
using UI;

namespace Controllers.Network
{
  public class CastNetwork : MonoBehaviourPun, INetworkFireballCaster
  {
    /// <summary>
    /// 请求发射火球（由 AttackRangeBase 调用）
    /// 功能：向其他玩家广播发射指令
    /// </summary>
    public void RequestFireball(
        Vector3 spawnPos,
        Vector3 direction,
        float speed,
        Element element
    )
    {
      photonView.RPC(
          "RPC_OnFireballCast",
          RpcTarget.Others,
          spawnPos,
          direction,
          speed,
          (int)element
      );
    }

    /// <summary>
    /// RPC：其他玩家收到后，在本地生成火发射物
    /// </summary>
    [PunRPC]
    void RPC_OnFireballCast(Vector3 spawnPos, Vector3 direction, float speed, int elementInt)
    {
      Element element = (Element)elementInt;
      SpawnFireballForOthers(spawnPos, direction, element);
    }

    /// <summary>
    /// 为其他玩家生成本地火球（isMine = false，不负责伤害判定）
    /// </summary>
    private void SpawnFireballForOthers(Vector3 spawnPos, Vector3 direction, Element element)
    {
      // 1. 根据元素类型选择视觉特效池
      string visualPool = GetVisualPoolByElement(element);
      GameObject visualObj = PoolHelper.Get(visualPool, spawnPos);
      if (visualObj != null)
      {
        visualObj.GetComponentInChildren<ParticleSystem>()?.Play();
        visualObj.transform.rotation = Quaternion.LookRotation(direction);
      }

      GameObject triggerObj = PoolHelper.Get(ObjectPoolConst.ImpactCannonTriggerPool, spawnPos);
      if (triggerObj != null)
      {
        ImpactCannon cannon = triggerObj.GetComponent<ImpactCannon>();
        if (cannon == null)
        {
          cannon = triggerObj.AddComponent<ImpactCannon>();
        }
        // 重要：传入 isMine = false，这个火球不会判定伤害
        //绑定token
        AttackToken token = new AttackToken
        {
          hitCollider = triggerObj,
          vfxEffect = visualObj,
          vfxPoolName = visualPool,
        };
        cannon.SetToken(token);
        cannon.StartShoot(direction, isMine: false);
      }
    }

    // ==================== 辅助方法 ====================

    /// <summary>
    /// 根据元素类型获取视觉特效池名
    /// </summary>
    private string GetVisualPoolByElement(Element element)
    {
      switch (element)
      {
        case Element.Lightning:
          return ObjectPoolConst.ImpactCannonLightenPool;
        case Element.Winter:
          return ObjectPoolConst.ImpactCannonWinterPool;
        default:
          return ObjectPoolConst.ImpactCannonCommonPool;
      }
    }

    // ==================== 伤害相关 ====================

    /// <summary>
    /// 广播伤害给所有客户端（由 ImpactCannon 调用）
    /// </summary>
    public void BroadcastDamage(
        GameObject enemyObj,
        float damage,
        bool isCritical,
        float criticalMultiplier,
        Vector3 hitPoint,
        Element element
    )
    {
      // 添加防御性检查
      if (this == null || gameObject == null)
      {
        Debug.LogWarning("[CastNetwork] 对象已销毁");
        return;
      }
      PhotonView enemyView = enemyObj.GetComponent<PhotonView>();
      if (enemyView == null)
        return;

      // 确保 photonView 有效
      if (photonView == null)
      {
        Debug.LogWarning("[CastNetwork] photonView 为空");
        return;
      }

      // 发给所有玩家：每个客户端通过事件通道分发伤害，EnemyBase.OnDamageReceived 校验 damgeTarget==gameObject 去重
      photonView.RPC(
          "RPC_DealDamage",
          RpcTarget.All,
          enemyView.ViewID,
          damage,
          isCritical,
          criticalMultiplier,
          hitPoint,
          (int)element
      );
      photonView.RPC(
          "RPC_ShowDamageNum",
          RpcTarget.All,
          damage,
          hitPoint,
          isCritical,
          criticalMultiplier
      );
    }

    /// <summary>
    /// RPC：所有客户端执行扣血和特效
    /// </summary>
    [PunRPC]
    void RPC_DealDamage(
        int enemyViewID,
        float damage,
        bool isCritical,
        float criticalMultiplier,
        Vector3 hitPoint,
        int elementInt
    )
    {
      // 1. 通过 ViewID 找到敌人对象
      PhotonView enemyView = PhotonView.Find(enemyViewID);
      if (enemyView == null)
        return;

      // 2. 触发伤害事件（扣血）
      // 注意：击中特效由各投射物系统自行处理，不在 RPC 中重复播放。
      // - ImpactCannon: ImpactCannon.OnTriggerEnter → PlayHitEffect()
      // - GuiLing:      GuiLingBase.OnTriggerEnter → LaunchEffect(hitVFX)
      Element element = (Element)elementInt;
      DamageEventArgs damageEventArgs = DamageEventArgs.GetShared(
          element,
          gameObject,
          enemyView.gameObject,
          damage,
          isCritical,
          criticalMultiplier
      );

      // 使用事件通道触发伤害事件
      var damageChannel = EventChannelLocator.MainContainer?.damageEventChannel;
      damageChannel?.Raise(damageEventArgs);
      Debug.Log($"[CastNetwork] 通过事件通道触发伤害，目标ViewID: {enemyViewID}");
    }

    /// <summary>
    /// RPC：所有客户端显示伤害数字
    /// 用于在敌人被攻击时，显示伤害数字
    /// </summary>
    /// <param name="damageValue"></param>
    /// <param name="position"></param>
    [PunRPC]
    void RPC_ShowDamageNum(
            float damageValue,
            Vector3 position,
            bool isCritical,
            float criticalMultiplier
        )
    {
      if (isCritical)
      {
        damageValue *= criticalMultiplier;
      }
      damageValue = Mathf.Ceil(damageValue);
      Vector3 spawnPos = position + Vector3.up * 0f;
      // 1. 从对象池获取伤害数字对象
      GameObject damageNumObj = PoolHelper.Get(ObjectPoolConst.DamageNumPool, spawnPos);
      if (damageNumObj != null)
      {
        DamageNum damageNum = damageNumObj.GetComponent<DamageNum>();
        if (damageNum != null)
        {
          damageNum.Play(damageValue, spawnPos, isCritical);
        }
      }
      else
      {
        Debug.LogError(
            $"DamageNumPool 为空，无法显示伤害数字：{damageValue}, {position}, {isCritical}"
        );
      }
    }

    // ==================== GuiLing（鬼灵弹）投射物同步 ====================

    /// <summary>
    /// 接口实现：请求广播 GuiLing 发射（由 AttackRange_BingNv 调用）
    /// </summary>
    public void RequestGuiLingCast(Vector3 spawnPos, Vector3 direction, int targetViewID, int elementInt)
    {
      photonView.RPC(
          "RPC_OnGuiLingCast",
          RpcTarget.Others,
          spawnPos,
          direction,
          targetViewID,
          elementInt
      );
    }

    /// <summary>
    /// RPC：其他客户端收到后，在本地生成 GuiLing 视觉投射物
    /// </summary>
    [PunRPC]
    void RPC_OnGuiLingCast(Vector3 spawnPos, Vector3 direction, int targetViewID, int elementInt)
    {
      Element element = (Element)elementInt;
      SpawnGuiLingForOthers(spawnPos, direction, targetViewID, element);
    }

    /// <summary>
    /// 为其他客户端生成本地 GuiLing（isMine = false，仅视觉表现）
    /// </summary>
    private void SpawnGuiLingForOthers(Vector3 spawnPos, Vector3 direction, int targetViewID, Element element)
    {
      string poolName = GetGuiLingPoolByElement(element);

      GameObject guiLing = PoolHelper.Get(poolName, spawnPos);
      if (guiLing == null)
      {
        Debug.LogWarning($"[CastNetwork] 从对象池 {poolName} 获取 GuiLing 失败");
        return;
      }

      // 查找目标
      PhotonView targetView = PhotonView.Find(targetViewID);
      Transform target = targetView != null ? targetView.transform : null;

      var guiLingBase = guiLing.GetComponent<GuiLingBase>();
      guiLingBase.poolName = poolName;
      guiLingBase.SetTargetAndLaunch(target, direction);
      // 重要：isMine = false，此投射物不负责伤害判定
      guiLingBase.SetDamageData(false, 0f, 0f, 1f, element);
      guiLingBase.SetSplitData(false, 0);
    }

    /// <summary>
    /// 根据元素类型获取 GuiLing 对象池名称
    /// </summary>
    private static string GetGuiLingPoolByElement(Element element)
    {
      switch (element)
      {
        case Element.Fire: return PoolConst.GuiLingFirePool;
        case Element.Lightning: return PoolConst.GuiLingLightningPool;
        case Element.Grass: return PoolConst.GuiLingGrassPool;
        case Element.Winter:
        default: return PoolConst.GuiLingWinterPool;
      }
    }

    // ==================== GuiLing 分裂弹同步 ====================

    /// <summary>
    /// 广播 GuiLing 分裂弹（由 GuiLingBase 命中时调用）
    /// 其他客户端收到后生成本地视觉分裂弹
    /// </summary>
    public void BroadcastSplitGuiLingCast(Vector3 spawnPos, Vector3 direction, GameObject targetEnemy, int elementInt)
    {
      PhotonView targetView = targetEnemy.GetComponent<PhotonView>();
      if (targetView == null)
        return;

      if (photonView == null)
        return;

      photonView.RPC(
          "RPC_OnSplitGuiLingCast",
          RpcTarget.Others,
          spawnPos,
          direction,
          targetView.ViewID,
          elementInt
      );
    }

    /// <summary>
    /// RPC：其他客户端收到后，在本地生成 GuiLing 分裂弹
    /// </summary>
    [PunRPC]
    void RPC_OnSplitGuiLingCast(Vector3 spawnPos, Vector3 direction, int targetViewID, int elementInt)
    {
      Element element = (Element)elementInt;
      SpawnGuiLingForOthers(spawnPos, direction, targetViewID, element);
    }

    // ==================== GuiLing 击中特效同步 ====================

    /// <summary>
    /// 广播 GuiLing 击中特效（由 GuiLingBase 命中时调用）
    /// 其他客户端在精确位置播放击中特效，确保所有玩家看到一致的命中效果
    /// </summary>
    public void BroadcastGuiLingHitVFX(Vector3 hitPos, Vector3 normal, int elementInt)
    {
      if (photonView == null)
        return;

      photonView.RPC(
          "RPC_PlayGuiLingHitVFX",
          RpcTarget.Others,
          hitPos,
          normal,
          elementInt
      );
    }

    /// <summary>
    /// RPC：其他客户端收到后，在本地播放 GuiLing 击中特效
    /// </summary>
    [PunRPC]
    void RPC_PlayGuiLingHitVFX(Vector3 hitPos, Vector3 normal, int elementInt)
    {
      Element element = (Element)elementInt;
      string hitPoolName = GetGuiLingHitPoolByElement(element);
      if (string.IsNullOrEmpty(hitPoolName))
        return;

      GameObject hitEffect = PoolHelper.Get(hitPoolName, hitPos);
      if (hitEffect == null)
        return;

      hitEffect.transform.position = hitPos;
      hitEffect.transform.rotation = Quaternion.FromToRotation(Vector3.up, normal);
      // GuiLingHit 脚本会在 OnEnable 中自动播放粒子并归还池
    }

    /// <summary>
    /// 根据元素类型获取 GuiLing 击中特效对象池名称
    /// </summary>
    private static string GetGuiLingHitPoolByElement(Element element)
    {
      switch (element)
      {
        case Element.Fire: return PoolConst.GuiLingHitFirePool;
        case Element.Lightning: return PoolConst.GuiLingHitLightningPool;
        case Element.Grass: return PoolConst.GuiLingHitGrassPool;
        case Element.Winter:
        default: return PoolConst.GuiLingHitWinterPool;
      }
    }

    // ==================== ImpactCannon 分裂弹（已有） ====================

    public void RequestSplitBullet(Vector3 spawnPos, Vector3 direction, int elementInt)
    {
      photonView.RPC(
          "RPC_OnSplitBulletCast",
          RpcTarget.Others,
          spawnPos,
          direction,
          elementInt
      );
    }

    [PunRPC]
    void RPC_OnSplitBulletCast(Vector3 spawnPos, Vector3 direction, int elementInt)
    {
      Element element = (Element)elementInt;
      SpawnSplitBulletForOthers(spawnPos, direction, element);
    }

    private void SpawnSplitBulletForOthers(Vector3 spawnPos, Vector3 direction, Element element)
    {
      // 为其他玩家生成分裂弹（只负责视觉表现）
      string visualPool = GetVisualPoolByElement(element);
      GameObject visualObj = PoolHelper.Get(visualPool, spawnPos);

      if (visualObj != null)
      {
        visualObj.GetComponentInChildren<ParticleSystem>()?.Play();
        visualObj.transform.rotation = Quaternion.LookRotation(direction);
      }

      GameObject triggerObj = PoolHelper.Get(ObjectPoolConst.ImpactCannonTriggerPool, spawnPos);

      if (triggerObj != null)
      {
        ImpactCannon cannon = triggerObj.GetComponent<ImpactCannon>();
        if (cannon != null)
        {
          cannon.StartShoot(direction, isMine: false);
          cannon.canSplit = false;

          AttackToken token = new AttackToken
          {
            hitCollider = triggerObj,
            vfxEffect = visualObj,
            vfxPoolName = visualPool,
          };
        }
      }
    }
  }
}

using System.Collections;
using System.Collections.Generic;
using Controllers.Character;
using Core;
using Controllers.Player;
using ExitGames.Client.Photon;
using ExitGames.Client.Photon.StructWrapping;
using Photon.Pun;
using UI.Framework.Panel;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using Hashtable = ExitGames.Client.Photon.Hashtable;
using Managers;
using UI;
using Controllers.Services;

namespace Controllers.Network
{
  public class Launcher : MonoBehaviourPunCallbacks, IObjectPoolService, IGameActionService
  {
    private bool isAutoCreate = false;
    private bool isJoiningRoom = false;
    private bool isQuittingToMenu = false;

    [SerializeField]
    public GameObject currentlySelectedCharacter;
    private Photon.Realtime.Player localPlayer;
    private InputField nameUI;
    private GameObject joinRoom;
    private GameObject TBGC;
    private GameObject joinRoomButton;
    private GameObject joinRoomInput;

    private bool isTest;

    // 拆分后的逻辑管理器
    private SpawnPointManager _spawnPointManager;
    private NetworkSceneFlow _sceneFlow;

    #region 单例模式
    public static Launcher instance;

    void Awake()
    {
      if (instance == null)
      {
        instance = this;
        DontDestroyOnLoad(gameObject);
        NetworkServiceLocator.RegisterObjectPoolService(this);
        NetworkServiceLocator.RegisterGameActionService(this);
      }
      else
      {
        Destroy(gameObject);
      }

      _sceneFlow = new NetworkSceneFlow(this);
      _spawnPointManager = new SpawnPointManager(this, currentlySelectedCharacter);

      // 只在大厅场景（场景索引1）初始化UI
      if (SceneManager.GetActiveScene().buildIndex == 1)
      {
        InitGetUI();
      }
    }
    #endregion

    void Start()
    {
      isTest = EventChannelLocator.MainContainer != null && EventChannelLocator.MainContainer.gameSettings != null && EventChannelLocator.MainContainer.gameSettings.IsTest;
      if (isTest)
        return;
      PhotonNetwork.AutomaticallySyncScene = true;
      UnityEngine.Application.runInBackground = true;
      PhotonNetwork.ConnectUsingSettings();
    }

    private void Update()
    {
      if (isTest)
        return;
      if (Input.GetKeyDown(KeyCode.Return))
      {
        ConfirmNickname();
      }
      if (Input.GetKeyDown(KeyCode.Escape))
      {
        CloseJoinRoomPanel();
      }
    }

    // ==================== 大厅 UI ====================

    public void ConfirmNickname()
    {
      if (string.IsNullOrEmpty(nameUI.text))
      {
        Debug.LogError("Name is empty");
        return;
      }
      else
      {
        PhotonNetwork.LocalPlayer.NickName = nameUI.text;
        Debug.Log($"修改昵称成功: {PhotonNetwork.LocalPlayer.NickName}");
      }
    }

    public void CloseJoinRoomPanel()
    {
      if (TBGC != null) TBGC.SetActive(false);
      if (joinRoomButton != null) joinRoomButton.SetActive(false);
      if (joinRoomInput != null) joinRoomInput.SetActive(false);
    }

    private void InitGetUI()
    {
      Debug.LogWarning("开始初始化UI组件---Launcher");
      nameUI = GameObject.Find("NameUI")?.GetComponent<InputField>();
      TBGC = GetInactiveObjectByName("TBGC");
      joinRoomButton = GetInactiveObjectByName("JoinRoomButton");
      joinRoomInput = GetInactiveObjectByName("JoinRoomInput");
      joinRoom = GameObject.Find("JoinRoom");

      // UI 初始化完成后注入 nameUI 到 SpawnPointManager
      _spawnPointManager.SetNameUI(nameUI);

      Initialize();
    }

    private void Initialize()
    {
      joinRoom
          .GetComponent<Button>()
          .onClick.AddListener(() =>
          {
            TBGC.SetActive(true);
            joinRoomButton.SetActive(true);
            joinRoomInput.SetActive(true);
          });

      joinRoomButton
          .GetComponent<Button>()
          .onClick.AddListener(() =>
          {
            string roomName = joinRoomInput.GetComponent<InputField>().text;
            if (string.IsNullOrEmpty(roomName))
            {
              Debug.LogError("Room name is empty");
              return;
            }
            {
              SwitchRoom(roomName);
            }
            CloseJoinRoomPanel();
          });

      if (TBGC != null)
      {
        Button closeBtn = TBGC.GetComponentInChildren<Button>(true);
        if (closeBtn != null && closeBtn.gameObject != joinRoomButton)
        {
          closeBtn.onClick.AddListener(CloseJoinRoomPanel);
        }
      }
    }

    public GameObject GetInactiveObjectByName(string objectName)
    {
      foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
      {
        if (root.name == objectName && !root.activeInHierarchy)
          return root;
        var found = FindChildRecursive(root.transform, objectName);
        if (found != null) return found.gameObject;
      }
      return null;
    }

    private static Transform FindChildRecursive(Transform parent, string name)
    {
      for (int i = 0; i < parent.childCount; i++)
      {
        var child = parent.GetChild(i);
        if (child.name == name) return child;
        var result = FindChildRecursive(child, name);
        if (result != null) return result;
      }
      return null;
    }

    // ==================== 连接 & 房间管理 ====================

    private string pendingRoomName = "";

    public void SwitchRoom(string newRoomName)
    {
      if (PhotonNetwork.InRoom)
      {
        pendingRoomName = newRoomName;
        isJoiningRoom = true;
        PhotonNetwork.LeaveRoom();
        Debug.Log("正在离开当前房间...");
      }
    }

    private void SetDefaultName()
    {
      if (string.IsNullOrEmpty(PhotonNetwork.LocalPlayer.NickName))
      {
        PhotonNetwork.LocalPlayer.NickName = "玩家" + PhotonNetwork.LocalPlayer.UserId;
      }
    }

    public override void OnConnectedToMaster()
    {
      if (isTest || SceneManager.GetActiveScene().buildIndex < 1)
        return;
      base.OnConnectedToMaster();
      PhotonNetwork.AutomaticallySyncScene = true;
      Debug.Log("Connected to master");
      string roomName = "Room_" + Random.Range(1000, 9999);
      SetDefaultName();
      if (!isAutoCreate)
      {
        PhotonNetwork.CreateRoom(
            roomName,
            new Photon.Realtime.RoomOptions() { MaxPlayers = 4, PublishUserId = true },
            default
        );
        isAutoCreate = true;
      }
    }

    public override void OnCreatedRoom()
    {
      if (isTest)
        return;
      base.OnCreatedRoom();
      Debug.Log("Created room: " + PhotonNetwork.CurrentRoom.Name);
    }

    public override void OnLeftRoom()
    {
      Debug.Log("已离开房间");
      if (isQuittingToMenu)
      {
        StartCoroutine(ShowAndLoadMainMenu());
        return;
      }
      // 切换房间：离开完成后安全地加入目标房间（OnLeftRoom 时已回到 Master 服务器）
      if (isJoiningRoom && !string.IsNullOrEmpty(pendingRoomName))
      {
        Debug.Log($"正在加入房间: {pendingRoomName}");
        PhotonNetwork.JoinRoom(pendingRoomName);
        isJoiningRoom = false;
      }
    }

    /// <summary>
    /// 退出房间并返回开始界面
    /// </summary>
    public void QuitToMainMenu()
    {
      if (PhotonNetwork.InRoom)
      {
        PhotonNetwork.AutomaticallySyncScene = false;
        _spawnPointManager.ClearLocalPlayerSpawnPoint();
        isQuittingToMenu = true;
        isAutoCreate = false;
        PhotonNetwork.LeaveRoom();
        Debug.Log("正在退出房间返回主菜单...");
      }
      else
      {
        StartCoroutine(ShowAndLoadMainMenu());
      }
    }

    private IEnumerator ShowAndLoadMainMenu()
    {
      yield return StartCoroutine(Loading.Instance.Show());
      LoadMainMenuScene();
    }

    private void LoadMainMenuScene()
    {
      isQuittingToMenu = false;
      pendingRoomName = "";
      isJoiningRoom = false;
      isAutoCreate = false;
      PhotonNetwork.AutomaticallySyncScene = false;
      SceneManager.LoadScene(0);
    }

    // ==================== PUN 回调路由 ====================

    public override void OnEnable()
    {
      base.OnEnable();
      SceneManager.sceneLoaded += OnSceneLoaded;
    }

    public override void OnDisable()
    {
      base.OnDisable();
      SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    public override void OnJoinedRoom()
    {
      Debug.Log("Joined room: " + PhotonNetwork.CurrentRoom.Name);
      if (isTest)
        return;
      base.OnJoinedRoom();
      _spawnPointManager.EnsurePlayerManagerExists();
      StartCoroutine(DelayJoinRoom());
    }

    IEnumerator DelayJoinRoom()
    {
      yield return new WaitForSeconds(0.5f);
      _spawnPointManager.CreatedOrJoinedRoom();
    }

    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
      if (scene.buildIndex == 1)
      {
        var roomJoinedChannel = EventChannelLocator.MainContainer.roomJoinedChannel;
        if (roomJoinedChannel != null)
          roomJoinedChannel.Raise(new RoomJoinedEventData());
      }

      if (EventChannelLocator.MainContainer.gameSettings.IsTest)
        return;

      if (scene.buildIndex == 1)
      {
        EventChannelLocator.MainContainer.gameSettings.IsStayLobby = true;
        InitGetUI();
        _sceneFlow.ResetForLobby();
        _sceneFlow.ResetLocalReady();

        if (PhotonNetwork.IsConnected && PhotonNetwork.InRoom)
        {
          StartCoroutine(_spawnPointManager.SpawnPlayerAfterDelay());
        }

        if (PhotonNetwork.IsConnected && !PhotonNetwork.InRoom && !isAutoCreate)
        {
          PhotonNetwork.AutomaticallySyncScene = true;
          string roomName = "Room_" + Random.Range(1000, 9999);
          SetDefaultName();
          PhotonNetwork.CreateRoom(
              roomName,
              new Photon.Realtime.RoomOptions() { MaxPlayers = 4, PublishUserId = true },
              default
          );
          isAutoCreate = true;
        }
        return;
      }

      if (scene.buildIndex > 1)
      {
        ServiceLocator.Get<GameManager>().isReady = false;
        EventChannelLocator.MainContainer.gameSettings.IsStayLobby = false;

        // 进入游戏场景时重置流程标志（非 MasterClient 的 isRoomLoading/isLoadingScene 不会被 LoadLevel 隐式重置）
        _sceneFlow.ResetForLobby();

        Hashtable loadProps = new Hashtable
            {
                { PlayerPropertyKeys.Level, true },
                { PlayerPropertyKeys.Loaded, true },
                { PlayerPropertyKeys.PlayerName, PhotonNetwork.LocalPlayer.NickName },
            };

        PhotonNetwork.LocalPlayer.SetCustomProperties(loadProps);
        Debug.Log(
            $"[Launcher] 本地玩家场景加载完成，设置 PlayerLoaded=true: {PhotonNetwork.LocalPlayer.NickName}"
        );

        _spawnPointManager.CreatedOrJoinedRoom();
      }
    }

    public override void OnPlayerLeftRoom(Photon.Realtime.Player otherPlayer)
    {
      _spawnPointManager.HandlePlayerLeftRoom(otherPlayer);
    }

    public override void OnPlayerPropertiesUpdate(
        Photon.Realtime.Player targetPlayer,
        Hashtable changedProps
    )
    {
      if (changedProps.ContainsKey(PlayerPropertyKeys.Level))
      {
        Debug.Log(
            $"玩家 {targetPlayer.NickName} 的 PlayerLevel 属性已更新: {changedProps[PlayerPropertyKeys.Level]}"
        );
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.Ready))
      {
        _sceneFlow.CheckAllPlayersReady();
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.Loaded))
      {
        _sceneFlow.CheckAllPlayersLoaded();
      }

      if (changedProps.ContainsKey(PlayerPropertyKeys.SpawnPoint))
      {
        object spawnPointValue = changedProps[PlayerPropertyKeys.SpawnPoint];
        Debug.Log($"玩家 {targetPlayer.NickName} 的生成点更新: {spawnPointValue}");
      }
    }

    void OnDestroy()
    {
      _spawnPointManager.HandleDestroy();
    }

    // ==================== 接口门面（IGameActionService / IObjectPoolService） ====================

    // IGameActionService
    public void SetLocalReady(bool ready) => _sceneFlow.SetLocalReady(ready);

    // IObjectPoolService
    public void ReturnToLobby() => _sceneFlow.ReturnToLobby();

    // CharactorPanel 直接调用
    public void SwitchCharacter(string newCharacterName) => _spawnPointManager.SwitchCharacter(newCharacterName);
  }
}

using System.Collections;
using UnityEngine;
using ExitGames.Client.Photon;
using Photon.Pun;
using Controllers.Services;
using UI.Framework.Panel;
using Hashtable = ExitGames.Client.Photon.Hashtable;

namespace Controllers.Network
{
    /// <summary>
    /// 准备系统、场景加载协调、返回大厅逻辑（从 Launcher 拆分）
    /// 非 MonoBehaviour 纯逻辑类，由 Launcher 持有和驱动协程
    /// </summary>
    public class NetworkSceneFlow
    {
        private readonly MonoBehaviour _coroutineRunner;

        private bool isRoomLoading = false;
        private bool isLoadingScene = false;
        private bool allPlayersLoaded = false;

        public NetworkSceneFlow(MonoBehaviour coroutineRunner)
        {
            _coroutineRunner = coroutineRunner;
        }

        // ==================== 准备系统 ====================

        /// <summary>设置本地玩家的准备状态</summary>
        public void SetLocalReady(bool ready)
        {
            if (!PhotonNetwork.InRoom)
            {
                Debug.LogWarning("[NetworkSceneFlow] 无法设置准备状态：未在房间中");
                return;
            }

            Hashtable props = new Hashtable { { PlayerPropertyKeys.Ready, ready } };
            PhotonNetwork.LocalPlayer.SetCustomProperties(props);
            Debug.Log($"[NetworkSceneFlow] 本地玩家准备状态: {ready} - {PhotonNetwork.LocalPlayer.NickName}");

            // 显式通知本地玩家的属性变更，确保本地 WorldSpaceUI 头顶文字能收到更新
            // （PUN2 的 OnPlayerPropertiesUpdate 不保证对本地客户端回调本地玩家的属性变更）
            var playerService = NetworkServiceLocator.PlayerService as PhotonPlayerService;
            if (playerService != null)
            {
                playerService.NotifyPropertyChanged(
                    PhotonNetwork.LocalPlayer.ActorNumber,
                    PlayerPropertyKeys.Ready,
                    ready
                );
            }

            CheckAllPlayersReady();
        }

        private bool AllPlayersReady()
        {
            foreach (Photon.Realtime.Player player in PhotonNetwork.PlayerList)
            {
                if (
                    !player.CustomProperties.ContainsKey(PlayerPropertyKeys.Ready)
                    || (bool)player.CustomProperties[PlayerPropertyKeys.Ready] == false
                )
                {
                    return false;
                }
            }
            return true;
        }

        public void CheckAllPlayersReady()
        {
            if (isRoomLoading || isLoadingScene)
            {
                return;
            }

            if (AllPlayersReady())
            {
                Debug.Log("[NetworkSceneFlow] 所有玩家已准备，开始加载场景");
                isRoomLoading = true;
                _coroutineRunner.StartCoroutine(LoadLevelAfterDelay());
            }
        }

        // ==================== 场景加载 ====================

        public IEnumerator LoadLevelAfterDelay(int index = 2)
        {
            isLoadingScene = true;
            yield return new WaitForSeconds(2f);

            yield return Loading.Instance.Show();

            if (PhotonNetwork.IsMasterClient)
            {
                PhotonNetwork.LoadLevel(index);
            }
        }

        /// <summary>检查所有玩家是否已加载场景（由 Launcher.OnPlayerPropertiesUpdate 委托）</summary>
        public void CheckAllPlayersLoaded()
        {
            if (isLoadingScene || allPlayersLoaded)
            {
                return;
            }

            foreach (Photon.Realtime.Player player in PhotonNetwork.PlayerList)
            {
                if (
                    !player.CustomProperties.ContainsKey(PlayerPropertyKeys.Loaded)
                    || (bool)player.CustomProperties[PlayerPropertyKeys.Loaded] == false
                )
                {
                    Debug.Log($"[NetworkSceneFlow] 等待玩家 {player.NickName} 加载场景...");
                    return;
                }
            }

            allPlayersLoaded = true;
            Debug.Log("[NetworkSceneFlow] 所有玩家已加载完成，开始游戏！");
        }

        // ==================== 返回大厅 ====================

        /// <summary>返回大厅（保持房间连接）</summary>
        public void ReturnToLobby()
        {
            if (!PhotonNetwork.InRoom)
            {
                Debug.LogWarning("[NetworkSceneFlow] 不在房间中，无法返回大厅");
                return;
            }

            _coroutineRunner.StartCoroutine(ReturnToLobbyCoroutine());
        }

        private IEnumerator ReturnToLobbyCoroutine()
        {
            yield return Loading.Instance.Show();

            if (PhotonNetwork.IsMasterClient)
            {
                PhotonNetwork.LoadLevel(1);
                Debug.Log("[NetworkSceneFlow] 房主发起切换到大厅场景");
            }
            else
            {
                Debug.Log("[NetworkSceneFlow] 等待房主同步场景...");
            }
        }

        // ==================== 状态重置（场景切换时由 Launcher 调用） ====================

        /// <summary>重置所有流程标志（大厅和游戏场景切换时均由 Launcher 调用）</summary>
        public void ResetForLobby()
        {
            isRoomLoading = false;
            isLoadingScene = false;
            allPlayersLoaded = false;
        }

        /// <summary>重置本地玩家的准备状态</summary>
        public void ResetLocalReady()
        {
            if (
                PhotonNetwork.IsConnected
                && PhotonNetwork.LocalPlayer.CustomProperties.ContainsKey(PlayerPropertyKeys.Ready)
            )
            {
                Hashtable props = new Hashtable { { PlayerPropertyKeys.Ready, false } };
                PhotonNetwork.LocalPlayer.SetCustomProperties(props);
                Debug.Log("[NetworkSceneFlow] 重置本地玩家就绪状态为 false");
            }
        }
    }
}

namespace Controllers.Network
{
    public static class PlayerPropertyKeys
    {
        public const string Ready = "PlayerReady";
        public const string Loaded = "PlayerLoaded";
        public const string Level = "PlayerLevel";
        public const string SpawnPoint = "CurrentSpawnPoint";
        public const string PlayerName = "playerName";
    }
}

using Controllers.Character;
using Controllers.Character.Pets;
using Controllers.Enemy;
using Core;
using Controllers.Item;
using Controllers.Services;
using Controllers.Time;
using Photon.Pun;
using UnityEngine;

namespace Controllers.Network
{
    /// <summary>
    /// Domain 层 RPC 桥接器（Infrastructure 层）
    /// 统一持有所有 Domain 层的 [PunRPC] 方法，通过公共方法委托回 Domain 对象
    /// 职责：纯粹的 RPC 转发，不包含业务逻辑
    /// </summary>
    public class DomainRpcBridge : MonoBehaviourPun, IDomainRpcService
    {
        public static DomainRpcBridge Instance { get; private set; }

        private SpiderBoss _spiderBossCache;

        /// <summary>注册场景中的 SpiderBoss 引用，避免每次 RPC 都做 FindObjectsByType</summary>
        public void RegisterSpiderBoss(SpiderBoss boss) => _spiderBossCache = boss;

        /// <summary>清除 SpiderBoss 缓存（Boss 销毁时调用）</summary>
        public void ClearSpiderBossCache() => _spiderBossCache = null;

        private SpiderBoss GetSpiderBoss()
        {
            // Unity 的 == 重载会在对象销毁后返回 true，所以这里天然支持缓存失效
            if (_spiderBossCache != null)
                return _spiderBossCache;
            var bosses = FindObjectsByType<SpiderBoss>(FindObjectsSortMode.None);
            if (bosses.Length > 0)
                _spiderBossCache = bosses[0];
            return _spiderBossCache;
        }

        void Awake()
        {
            if (Instance != null)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);

            // 注册到 NetworkServiceLocator，供 Domain 层通过接口调用
            NetworkServiceLocator.RegisterDomainRpcService(this);
        }

        void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        // ============================================================
        // SyncedGameTimeManager RPC
        // ============================================================

        [PunRPC]
        public void RPC_SyncStartCaTime()
        {
            SyncedGameTimeManager.HandleSyncStartCaTime();
        }

        [PunRPC]
        public void RPC_OnTimeEventTriggered(string eventId, float triggerTime)
        {
            SyncedGameTimeManager.HandleOnTimeEventTriggered(eventId, triggerTime);
        }

        [PunRPC]
        public void RPC_GameTimeFinished()
        {
            SyncedGameTimeManager.HandleGameTimeFinished();
        }

        [PunRPC]
        public void RPC_SyncSetTime(float time)
        {
            SyncedGameTimeManager.HandleSyncSetTime(time);
        }

        [PunRPC]
        public void RPC_SyncStartTime()
        {
            SyncedGameTimeManager.HandleSyncStartTime();
        }

        [PunRPC]
        public void RPC_SyncPauseTime()
        {
            SyncedGameTimeManager.HandleSyncPauseTime();
        }

        [PunRPC]
        public void RPC_SyncResetTime()
        {
            SyncedGameTimeManager.HandleSyncResetTime();
        }

        [PunRPC]
        public void RPC_BossSpawn(string bossName)
        {
            SyncedGameTimeManager.HandleBossSpawn(bossName);
        }

        // ============================================================
        // PlayerController RPC
        // ============================================================

        [PunRPC]
        public void NoticeOtherPlayerDamage(string playerId, float maxHP, float currentHP)
        {
            if (EventChannelLocator.MainContainer?.healthUpdateChannel != null)
            {
                EventChannelLocator.MainContainer.healthUpdateChannel.Raise(
                    HealthUpdateData.OtherPlayer(playerId, maxHP, currentHP));
            }
        }

        [PunRPC]
        public void RPC_SyncPlayerElement(int actorNumber, int elementInt)
        {
            PlayerController.HandleSyncPlayerElement(actorNumber, elementInt);
        }

        // ============================================================
        // WizardBoy RPC
        // ============================================================

        [PunRPC]
        public void RPC_InitElementPool(int viewID, int elementInt)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var wizardBoy = go.GetComponent<WizardBoy>();
                if (wizardBoy != null)
                {
                    wizardBoy.HandleInitElementPool(elementInt);
                }
            }
        }

        // ============================================================
        // Boss_Horror (SpiderBoss) RPC
        // ============================================================

        [PunRPC]
