using System.Collections;
using System.Collections.Generic;
using Controllers.Enemy;
using Controllers.Network;
using Controllers.Item;
using Photon.Pun;
using UnityEngine;
using Core;
using Core.Channels.General;

namespace Controllers.Network
{
  /// <summary>
  /// 统一网络对象池管理器（怪物 + 掉落物）
  /// 用法：
  ///   生成怪物：NetworkObjectPoolManager.instance.Spawn(NetworkObjectPoolConst.Skeleton, position);
  ///   回收怪物：NetworkObjectPoolManager.instance.Despawn(NetworkObjectPoolConst.Skeleton, gameObject);
  ///   生成掉落物：NetworkObjectPoolManager.instance.Spawn(NetworkObjectPoolConst.ExperienceBall_Blue, position);
  ///   回收掉落物：NetworkObjectPoolManager.instance.Despawn(NetworkObjectPoolConst.ExperienceBall_Blue, gameObject);
  /// </summary>
  public class NetworkObjectPoolManager : MonoBehaviourPunCallbacks, IPunPrefabPool
  {
    #region 单例模式

    public static NetworkObjectPoolManager instance;

    void Awake()
    {
      if (instance == null)
      {
        instance = this;
      }
      else
        Destroy(gameObject);
    }

    void OnEnable()
    {
      EventChannelLocator.MainContainer.poolOperationChannel.RegisterListener(OnPoolOperation);
    }

    void OnDisable()
    {
      EventChannelLocator.MainContainer.poolOperationChannel.UnregisterListener(OnPoolOperation);
    }

    private void OnPoolOperation(PoolOperationData data)
    {
      switch (data.operationType)
      {
        case PoolOperationType.Spawn:
          var obj = Spawn(data.poolName, data.position, data.rotation);
          data.resultCallback?.Invoke(obj);
          break;
        case PoolOperationType.Despawn:
          Despawn(data.poolName, data.targetObject, data.delay);
          break;
        case PoolOperationType.DespawnAll:
          if (string.IsNullOrEmpty(data.poolName))
            DespawnAll();
          else
            DespawnAll(data.poolName);
          break;
      }
    }
    #endregion

    // ===================== Inspector 配置 =====================
    [System.Serializable]
    public class PoolConfig
    {
      [Tooltip("与 NetworkObjectPoolConst 中常量保持一致")]
      public string poolName;
      public GameObject prefab;

      [Tooltip("游戏启动时预创建的数量")]
      public int preloadCount = 5;
    }

    [Header("网络对象池配置（在 Inspector 中添加）")]
    [SerializeField]
    private List<PoolConfig> poolConfigs = new List<PoolConfig>();

    // ===================== 内部数据 =====================
    private Dictionary<string, Queue<GameObject>> pools =
        new Dictionary<string, Queue<GameObject>>();
    private Dictionary<string, GameObject> prefabs = new Dictionary<string, GameObject>();
    private readonly Dictionary<string, HashSet<GameObject>> _activeObjects = new();
    private bool photonReady = false;

    // ===================== 初始化 =====================
    void Start()
    {
      PhotonNetwork.PrefabPool = this;

      if (EventChannelLocator.MainContainer.gameSettings.IsTest || (PhotonNetwork.IsConnectedAndReady && PhotonNetwork.InRoom))
      {
        InitPools();
        photonReady = true;
      }
    }

    void Update()
    {
      // 等待 Photon 就绪后再初始化（仅网络模式）
      if (
          !photonReady
          && !EventChannelLocator.MainContainer.gameSettings.IsTest
          && PhotonNetwork.IsConnectedAndReady
          && PhotonNetwork.InRoom
      )
      {
        InitPools();
        photonReady = true;
      }
    }

    private void InitPools()
    {
      foreach (var cfg in poolConfigs)
      {
        if (cfg.prefab == null)
        {
          Debug.LogWarning($"[NetworkObjectPool] {cfg.poolName} 未配置预制体");
          continue;
        }
        prefabs[cfg.poolName] = cfg.prefab;
        pools[cfg.poolName] = new Queue<GameObject>();
        Preload(cfg.poolName, cfg.preloadCount);
      }
      Debug.Log("[NetworkObjectPool] 初始化完成");
    }

    // ===================== 公共接口 =====================

    /// <summary>
    /// 运行时动态注册对象池（由生成器等组件在 Start 中调用）
    /// 如果池名已存在则跳过，不会重复注册
    /// </summary>
    /// <param name="poolName">池名称</param>
    /// <param name="prefab">预制体引用</param>
    /// <param name="preloadCount">预创建数量</param>
    public void RegisterPool(string poolName, GameObject prefab, int preloadCount = 10)
    {
      if (string.IsNullOrEmpty(poolName) || prefab == null)
        return;
      if (pools.ContainsKey(poolName))
        return; // 已存在，不重复注册

      this.prefabs[poolName] = prefab;
      pools[poolName] = new Queue<GameObject>();
      Preload(poolName, preloadCount);
      Debug.Log($"[NetworkObjectPool] 运行时注册池: {poolName}, 预加载 x{preloadCount}");
    }

    /// <summary>生成对象，自动处理测试模式与网络模式</summary>
    public GameObject Spawn(string poolName, Vector3 position, Quaternion rotation = default)
    {
      if (rotation == default)
        rotation = Quaternion.identity;

      if (EventChannelLocator.MainContainer.gameSettings.IsTest)
        return GetFromPool(poolName, position, rotation);

      if (!PhotonNetwork.IsMasterClient)
      {
        Debug.LogWarning("[NetworkObjectPool] 只有房主可以生成网络对象");
        return null;
      }
      return PhotonNetwork.Instantiate(poolName, position, rotation);
    }

    /// <summary>回收对象，支持延迟回收</summary>
    public void Despawn(string poolName, GameObject obj, float delay = 0f)
    {
      if (obj == null)
        return;
      if (delay > 0f)
        StartCoroutine(DespawnDelay(poolName, obj, delay));
      else
        DespawnNow(poolName, obj);
    }

    /// <summary>回收该池内所有激活中的怪物</summary>
    public void DespawnAll(string poolName)
    {
      if (!EventChannelLocator.MainContainer.gameSettings.IsTest && !PhotonNetwork.IsMasterClient)
        return;
      if (!_activeObjects.TryGetValue(poolName, out var active) || active.Count == 0)
        return;

      foreach (var obj in new List<GameObject>(active))
      {
        if (obj != null && obj.activeSelf)
          DespawnNow(poolName, obj);
      }
    }

    /// <summary>回收所有池的对象</summary>
    public void DespawnAll()
    {
      foreach (var poolName in new List<string>(prefabs.Keys))
        DespawnAll(poolName);
    }

    // ===================== IPunPrefabPool 实现（Photon 回调） =====================

    /// <summary>Photon 调用：必须返回未激活的对象，Photon 自行激活</summary>
    public GameObject Instantiate(string prefabId, Vector3 position, Quaternion rotation)
    {
      // 库内对象（怪物/掉落物）走对象池
      if (prefabs.ContainsKey(prefabId))
        return GetFromPool(prefabId, position, rotation, activateOnGet: false);

      // 非库内对象（如玩家）回退到默认 Resources 加载
      var prefab = Resources.Load<GameObject>(prefabId);
      if (prefab != null)
        return Object.Instantiate(prefab, position, rotation);

      Debug.LogError(
          $"[NetworkObjectPool] 无法实例化: {prefabId}，未在对象池或 Resources 中找到"
      );
      return null;
    }

    public void Destroy(GameObject go)
    {
      string poolName = FindPoolName(go);
      if (string.IsNullOrEmpty(poolName))
      {
        Object.Destroy(go);
        return;
      }
      ReturnToPool(poolName, go);
    }

    // ===================== 内部方法 =====================

    private IEnumerator DespawnDelay(string poolName, GameObject obj, float delay)
    {
      yield return new WaitForSeconds(delay);
      DespawnNow(poolName, obj);
    }

    private void DespawnNow(string poolName, GameObject obj)
    {
      if (EventChannelLocator.MainContainer.gameSettings.IsTest)
      {
        // 测试模式：直接本地回池
        ReturnToPool(poolName, obj);
      }
      else
      {
        // 网络模式：使用 PhotonNetwork.Destroy 同步销毁到所有客户端
        // Destroy 会触发 IPunPrefabPool.Destroy() 回调，在那里执行回池
        if (PhotonNetwork.IsConnectedAndReady)
        {
          PhotonNetwork.Destroy(obj);
        }
        else
        {
          ReturnToPool(poolName, obj);
        }
      }
    }

    private GameObject GetFromPool(
        string poolName,
        Vector3 position,
        Quaternion rotation,
        bool activateOnGet = true
    )
    {
      // 从池中取出可用对象
      if (pools.TryGetValue(poolName, out var pool))
      {
        while (pool.Count > 0)
        {
          var obj = pool.Dequeue();
          if (obj == null)
            continue;
          obj.transform.SetPositionAndRotation(position, rotation);
          // 取出时重新启用 PhotonView（预加载时禁用过）
          var photonView = obj.GetComponent<PhotonView>();
          if (photonView != null)
            photonView.enabled = true;
          if (activateOnGet)
            obj.SetActive(true);
          TrackActive(poolName, obj);
          return obj;
        }
      }

      // 池空了则动态创建
      if (prefabs.TryGetValue(poolName, out var prefab))
      {
        //创建对象并且添加到对象池
        var newObj = Object.Instantiate(prefab, position, rotation);
        newObj.name = poolName;
        newObj.SetActive(false);
        // ✅ 不要放回池子，直接返回使用
        // ✅ 尊重 activateOnGet 参数
        if (activateOnGet)
          newObj.SetActive(true);
        else
          newObj.SetActive(false);
        TrackActive(poolName, newObj);
        return newObj;
      }

      Debug.LogError($"[NetworkObjectPool] 未找到预制体: {poolName}");
      return null;
    }

    private void ReturnToPool(string poolName, GameObject obj)
    {
      if (obj == null)
        return;

      UntrackActive(poolName, obj);

      // 重置对应组件状态
      obj.GetComponent<EnemyBase>()?.ResetState();
      obj.GetComponent<DropItemBase>()?.ResetState();
      obj.SetActive(false);
      obj.name = poolName; // 统一标记名称，方便 FindPoolName 匹配
      obj.transform.SetParent(transform);
      obj.transform.SetLocalPositionAndRotation(Vector3.zero, Quaternion.identity);

      var rb = obj.GetComponent<Rigidbody>();
      if (rb != null)
      {
        rb.velocity = Vector3.zero;
        rb.angularVelocity = Vector3.zero;
      }

      if (!pools.ContainsKey(poolName))
        pools[poolName] = new Queue<GameObject>();
      pools[poolName].Enqueue(obj);
    }

    private void Preload(string poolName, int count)
    {
      for (int i = 0; i < count; i++)
      {
        // 预加载时先禁用 PhotonView，防止本地 Instantiate 触发 Photon 网络销毁流程
        var obj = Object.Instantiate(prefabs[poolName], Vector3.zero, Quaternion.identity);
        obj.name = poolName;
        var photonView = obj.GetComponent<PhotonView>();
        if (photonView != null)
          photonView.enabled = false;
        ReturnToPool(poolName, obj);
      }
      Debug.Log($"[NetworkObjectPool] 预创建 {poolName} x{count}");
    }

    /// <summary>通过对象名称反查所属池（回收时已统一设为 poolName）</summary>
    private string FindPoolName(GameObject obj)
    {
      // 优先精确匹配：回收时已将 name 设为 poolName
      if (pools.ContainsKey(obj.name))
        return obj.name;

      // 备用模糊匹配：应对网络模式下 Photon 返回的对象（名称可能带 (Clone) 等后缀）
      foreach (var kvp in prefabs)
      {
        if (obj.name.Contains(kvp.Value.name) || obj.name.Contains(kvp.Key))
          return kvp.Key;
      }

      Debug.LogWarning($"[NetworkObjectPool] FindPoolName 失败，无法识别对象: {obj.name}");
      return null;
    }

    // ===================== 活跃对象追踪 =====================

    private void TrackActive(string poolName, GameObject obj)
    {
      if (!_activeObjects.TryGetValue(poolName, out var set))
      {
        set = new HashSet<GameObject>();
        _activeObjects[poolName] = set;
      }
      set.Add(obj);
    }

    private void UntrackActive(string poolName, GameObject obj)
    {
      if (_activeObjects.TryGetValue(poolName, out var set))
        set.Remove(obj);
    }

    // ===================== 调试工具 =====================

    public int GetPoolCount(string poolName) =>
        pools.TryGetValue(poolName, out var pool) ? pool.Count : 0;

    // ===================== 销毁清理 =====================

    void OnDestroy()
    {
      foreach (var pool in pools.Values)
        while (pool.Count > 0)
        {
          var obj = pool.Dequeue();
          if (obj)
            Object.Destroy(obj);
        }

      pools.Clear();
      prefabs.Clear();
      _activeObjects.Clear();
    }
  }

  /// <summary>
  /// 网络对象池名称常量
  /// 与 Inspector 中 PoolConfig.poolName 保持一致
  /// </summary>
  public static class NetworkObjectPoolConst
  {
    // 掉落物
    public const string ExperienceBall_Blue = "ExperienceBall_BluePool";

    // 怪物
    public const string Skeleton = "SkeletonPool";
  }
}

using System.Collections.Generic;
using Controllers.Services;
using Photon.Pun;
using Photon.Realtime;
using UnityEngine;

namespace Controllers.Network
{
    public class PhotonPlayerService : INetworkPlayerService
    {
        private readonly Dictionary<int, Photon.Realtime.Player> _playerCache = new();

        public event System.Action<int, string, object> OnPlayerPropertyChanged;
        public event System.Action<int, string> OnPlayerEnteredRoom;
        public event System.Action<int, string> OnPlayerLeftRoom;
        public event System.Action OnLocalJoinedRoom;

        public bool IsConnectedAndInRoom => PhotonNetwork.IsConnectedAndReady && PhotonNetwork.InRoom;
        public bool IsMasterClient => PhotonNetwork.IsMasterClient;

        public int GetLocalActorNumber()
        {
            if (PhotonNetwork.LocalPlayer != null)
                return PhotonNetwork.LocalPlayer.ActorNumber;
            return -1;
        }

        public string GetLocalUserId()
        {
            if (PhotonNetwork.LocalPlayer != null)
                return PhotonNetwork.LocalPlayer.UserId;
            return string.Empty;
        }

        public bool IsOwnerOf(GameObject gameObject)
        {
            if (gameObject == null) return false;
            PhotonView pv = gameObject.GetComponentInParent<PhotonView>();
            return pv != null && pv.IsMine;
        }

        public void SetCustomProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom) return;
            var props = new ExitGames.Client.Photon.Hashtable { { key, value } };
            PhotonNetwork.LocalPlayer.SetCustomProperties(props);
        }

        public object GetCustomProperty(string key)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.LocalPlayer == null)
                return null;
            return PhotonNetwork.LocalPlayer.CustomProperties[key];
        }

        public int[] GetAllActorNumbers()
        {
            if (!IsConnectedAndInRoom) return System.Array.Empty<int>();
            var players = PhotonNetwork.PlayerList;
            int[] actorNumbers = new int[players.Length];
            for (int i = 0; i < players.Length; i++)
            {
                actorNumbers[i] = players[i].ActorNumber;
            }
            return actorNumbers;
        }

        public object GetPlayerCustomProperty(int actorNumber, string key)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.CustomProperties[key] : null;
        }

        public string GetPlayerUserId(int actorNumber)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.UserId : null;
        }

        public string GetPlayerNickName(int actorNumber)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.NickName : null;
        }

        public bool AllPlayersHaveProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom) return false;
            foreach (var player in PhotonNetwork.PlayerList)
            {
                if (!player.CustomProperties.ContainsKey(key))
                    return false;
                if (!player.CustomProperties[key].Equals(value))
                    return false;
            }
            return true;
        }

        public void SetRoomCustomProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.CurrentRoom == null) return;
            var props = new ExitGames.Client.Photon.Hashtable { { key, value } };
            PhotonNetwork.CurrentRoom.SetCustomProperties(props);
        }

        public object GetRoomCustomProperty(string key)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.CurrentRoom == null)
                return null;
            return PhotonNetwork.CurrentRoom.CustomProperties[key];
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发 PUN 属性变更事件
        /// </summary>
        public void NotifyPropertyChanged(int actorNumber, string key, object value)
        {
            OnPlayerPropertyChanged?.Invoke(actorNumber, key, value);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发玩家加入事件
        /// </summary>
        public void NotifyPlayerEnteredRoom(int actorNumber, string userId)
        {
            var player = FindPlayer(actorNumber);
            if (player != null)
                _playerCache[actorNumber] = player;
            OnPlayerEnteredRoom?.Invoke(actorNumber, userId);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发玩家离开事件
        /// </summary>
        public void NotifyPlayerLeftRoom(int actorNumber, string userId)
        {
            _playerCache.Remove(actorNumber);
            OnPlayerLeftRoom?.Invoke(actorNumber, userId);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发本地玩家加入完成事件
        /// </summary>
        public void NotifyLocalJoinedRoom()
        {
            _playerCache.Clear();
            foreach (var player in PhotonNetwork.PlayerList)
                _playerCache[player.ActorNumber] = player;
            OnLocalJoinedRoom?.Invoke();
        }

        private Photon.Realtime.Player FindPlayer(int actorNumber)
        {
            if (_playerCache.TryGetValue(actorNumber, out var cached))
                return cached;
            foreach (var player in PhotonNetwork.PlayerList)
            {
                if (player.ActorNumber == actorNumber)
                {
                    _playerCache[actorNumber] = player;
                    return player;
                }
            }
            return null;
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Photon.Pun;

namespace Controllers.Network
{
    public class PlayerStateSync : MonoBehaviourPun, IPunObservable
    {
        [SerializeField] private SpriteRenderer spriteRenderer;
        private bool networkFlipX;

        void Start()
        {
            spriteRenderer = GetComponentInChildren<SpriteRenderer>();
        }

        // Update is called once per frame
        void Update()
        {
            if (photonView.IsMine)
            {
                return;
            }
            else
            {
                // 应用网络状态
                spriteRenderer.flipX = networkFlipX;
            }
        }

        public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
        {
            if (stream.IsWriting)
            {
                // 发送玩家状态
                stream.SendNext(spriteRenderer.flipX);
            }
            else
            {
                // 接收玩家状态
                networkFlipX = (bool)stream.ReceiveNext();
            }
        }
    }
}

using System.Collections;
using Managers;
using Core;
using Core.Channels.Game;
using Controllers.PowerUp;
using Controllers.Services;
using Photon.Pun;
using UI;
using UnityEngine;

namespace Controllers.Network
{
    /// <summary>
    /// Application 层 RPC 桥接器（Infrastructure 层）
    /// 统一持有所有 Application 层的 [PunRPC] 方法，通过静态方法委托回 Application 管理器
    /// 职责：纯粹的 RPC 转发，不包含业务逻辑
    /// </summary>
    public class AppRpcBridge : MonoBehaviourPun
    {
        public static AppRpcBridge Instance { get; private set; }

        void Awake()
        {
            if (Instance != null)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }

        void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        // ============================================================
        // GamePauseManager RPC
        // ============================================================

        [PunRPC]
