    {
        public const string Ready = "PlayerReady";
        public const string Loaded = "PlayerLoaded";
        public const string Level = "PlayerLevel";
        public const string SpawnPoint = "CurrentSpawnPoint";
        public const string PlayerName = "playerName";
    }
